import requests
from xml.etree import ElementTree as ET
queries=['apelin-13 peri-infarct myocardial infarction','apelin-13 infusion myocardial infarction cardiac function','apelin 13 infarct border zone salvage']
for q in queries:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':10,'retmode':'json'},timeout=20)
 ids=r.json()['esearchresult']['idlist']
 print('\nQUERY',q,'IDS',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
